import {MONTHS,WEEKDAYS,monthWeeks,getDay,parseDate,list} from './model.js';
export function timeLabel(t){if(!/^\d{2}:\d{2}$/.test(t))return t;const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'a. m.':'p. m.'}`;}
function wrap(ctx,text,width){const out=[];for(const para of String(text||'').split('\n')){let line='';for(const word of para.split(/\s+/)){if(!word)continue;let candidate=line?line+' '+word:word;if(ctx.measureText(candidate).width>width&&line){out.push(line);line=word;}else line=candidate;while(ctx.measureText(line).width>width&&line.length>1){let n=line.length-1;while(n>1&&ctx.measureText(line.slice(0,n)).width>width)n--;out.push(line.slice(0,n));line=line.slice(n);}}out.push(line);}return out;}
export async function makePNG(state,year,month,week=null){const weeks=week?[week]:monthWeeks(year,month);const names=Object.fromEntries(list(state,'person').map(p=>[p.id,p.name]));const W=2100,pad=42,cw=(W-pad*2)/7;const measure=document.createElement('canvas').getContext('2d');measure.font='23px Arial';
 const blocks=weeks.map(dates=>dates.map(k=>{const d=getDay(state,k),inside=week||parseDate(k).getMonth()===month;const rows=[];if(inside){if(d.note)rows.push({text:d.note,color:'#ad354a',bold:false});for(const m of d.masses){rows.push({text:timeLabel(m.time)+(m.title?' · '+m.title:''),color:'#003fa3',bold:true});if(m.place&&m.place!=='Parroquia')rows.push({text:m.place,color:'#66758a',small:true});if(m.note)rows.push({text:m.note,color:'#ad354a'});rows.push({text:m.personIds.map(id=>names[id]||'Participante archivado').join(', ')||'Por asignar',color:m.personIds.length?'#172941':'#97a5b5'});rows.push({text:'',gap:true});}}const rendered=rows.map(r=>{measure.font=`${r.bold?'bold ':''}${r.small?19:23}px Arial`;return {...r,lines:r.gap?[]:wrap(measure,r.text,cw-32)};});return {k,inside,d,rows:rendered,height:65+rendered.reduce((n,r)=>n+(r.gap?10:r.lines.length*(r.small?26:32)),0)};}));
 const heights=blocks.map(row=>Math.max(190,...row.map(c=>c.height)));const H=230+heights.reduce((a,b)=>a+b,0)+72;const canvas=document.createElement('canvas');const scale=Math.min(1,Math.sqrt(12000000/(W*H)));if(scale<0.5)throw Error('Este mes tiene demasiado contenido para una sola imagen legible. Expórtalo por semana.');canvas.width=Math.floor(W*scale);canvas.height=Math.floor(H*scale);const ctx=canvas.getContext('2d');ctx.scale(scale,scale);ctx.fillStyle='white';ctx.fillRect(0,0,W,H);ctx.fillStyle='#003fa3';ctx.font='bold 58px Arial';ctx.fillText('Rol Monaguillos',pad,84);ctx.fillStyle='#182942';ctx.font='30px Arial';ctx.fillText(`${MONTHS[month].toUpperCase()} ${year}`+(week?` · ${week[0].slice(8)}–${week[6].slice(8)}`:''),pad,133);ctx.fillStyle='#66758a';ctx.font='20px Arial';ctx.fillText('PARROQUIA ANUNCIACIÓN A MARÍA',pad,171);
 try{const logo=new Image();logo.src='./logo.png';await logo.decode();ctx.drawImage(logo,W-285,25,240,145);}catch{}
 let y=199;for(let i=0;i<7;i++){ctx.fillStyle='#003fa3';ctx.fillRect(pad+i*cw,y,cw,47);ctx.fillStyle='white';ctx.font='bold 20px Arial';ctx.textAlign='center';ctx.fillText(WEEKDAYS[i].toUpperCase(),pad+i*cw+cw/2,y+30);}ctx.textAlign='left';y+=47;
 blocks.forEach((row,ri)=>{row.forEach((c,ci)=>{const x=pad+ci*cw,h=heights[ri];ctx.fillStyle=!c.inside?'#f4f6f8':ci===0?'#edf5ff':'white';ctx.fillRect(x,y,cw,h);ctx.strokeStyle='#b7cae1';ctx.lineWidth=1.5;ctx.strokeRect(x,y,cw,h);ctx.fillStyle=c.inside?'#003fa3':'#b0bac7';ctx.font='bold 29px Arial';ctx.fillText(String(parseDate(c.k).getDate()),x+15,y+38);let yy=y+70;for(const r of c.rows){if(r.gap){yy+=10;continue;}ctx.fillStyle=r.color;ctx.font=`${r.bold?'bold ':''}${r.small?19:23}px Arial`;for(const line of r.lines){ctx.fillText(line,x+15,yy);yy+=r.small?26:32;}}});y+=heights[ri];});ctx.fillStyle='#66758a';ctx.font='17px Arial';ctx.fillText('Servicio con alegría · Calendario de domingo a sábado',pad,H-24);
 const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('No se pudo generar la imagen.');return {blob,canvas,filename:`Rol-${year}-${String(month+1).padStart(2,'0')}${week?'-semana-'+week[0]:''}.png`};}
export function download(blob,filename){const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);}
